study_gl::GLuint name = 0;
gl.GenBuffers(1, &name);
gl.BindBuffer(study_gl::ArrayBuffer, name);
gl.BufferData(study_gl::ArrayBuffer, 24, vertices.data(), study_gl::StaticDraw);

void (STUDY_GL_CALL* GenBuffers)(GLsizei, GLuint*) = nullptr;
void (STUDY_GL_CALL* BindBuffer)(GLenum, GLuint) = nullptr;
void (STUDY_GL_CALL* BufferData)(GLenum, GLsizeiptr, const void*, GLenum) = nullptr;
void (STUDY_GL_CALL* DeleteBuffers)(GLsizei, const GLuint*) = nullptr;
void (STUDY_GL_CALL* GetBufferParameteriv)(GLenum, GLenum, GLint*) = nullptr;
void (STUDY_GL_CALL* GetBufferSubData)(GLenum, GLintptr, GLsizeiptr, void*) = nullptr;

const std::size_t bytes = study_mesh::byte_count(vertices);
if (bytes > static_cast<std::size_t>(std::numeric_limits<GLsizeiptr>::max())) {
    std::fprintf(stderr, "VertexBuffer::upload: mesh too large for GL\n");
    return false;
}
gl_.BufferData(ArrayBuffer, static_cast<GLsizeiptr>(bytes),
               vertices.data(), StaticDraw);

VertexBuffer::~VertexBuffer() noexcept { reset(); }

void VertexBuffer::reset() noexcept {
    if (name_ != 0) {
        gl_.DeleteBuffers(1, &name_);
        name_ = 0;
    }
}

gl_.GenBuffers(1, &name_);
if (!stage_ok(gl_, "glGenBuffers") || name_ == 0) {
    reset();
    return false;
}
gl_.BindBuffer(ArrayBuffer, name_);
if (!stage_ok(gl_, "glBindBuffer")) {
    reset();
    return false;
}

study_gl::VertexBuffer vertex_buffer(gl);
{
    const auto vertices = study_mesh::make_triangle();
    if (!vertex_buffer.upload(vertices)) return 1;
}
study_gl::GLint stored_bytes = 0;
gl.GetBufferParameteriv(study_gl::ArrayBuffer, study_gl::BufferSize, &stored_bytes);
if (gl.GetError() != 0 || stored_bytes != 24) return 1;
std::printf("GL vertex buffer stores %d bytes (not drawn)\n", stored_bytes);

study_mesh::Triangle actual{};
gl.GetBufferSubData(study_gl::ArrayBuffer, 0,
    static_cast<study_gl::GLsizeiptr>(study_mesh::byte_count(actual)), actual.data());
if (gl.GetError() != 0) return false;
const auto expected = study_mesh::make_triangle();
for (std::size_t i = 0; i < actual.size(); ++i) {
    if (actual[i].x != expected[i].x || actual[i].y != expected[i].y) return false;
}

